package br.com.folha.notes;
public class KanaPaperTest {
 public static void main(String[] args){int count=0;for(String type:StudyPaper.LINES.keySet()){for(float[] l:StudyPaper.LINES.get(type))for(int i=0;i<4;i++)if(!Float.isFinite(l[i])||l[i]<0||l[i]>(i%2==0?595:842))throw new AssertionError("Bounds "+type);StudyPaper.Guide[] guides=StudyPaper.GUIDES.get(type);for(StudyPaper.Guide g:guides){if(g.x<0||g.y<0||g.x+g.size*g.text.length()>561.01f||g.y+g.size>842)throw new AssertionError("Guide bounds "+type);for(char c:g.text.toCharArray())if(!KanaGlyphs.DATA.containsKey(String.valueOf(c)))throw new AssertionError("Missing kana "+c);}if(type.startsWith("hiragana-p")||type.startsWith("katakana-p"))count++;}if(count!=54||Paper.IDS.length!=21||KanaGlyphs.DATA.size()!=151)throw new AssertionError("Coverage");for(String data:KanaGlyphs.DATA.values())GlyphData.contours(data);if(JapaneseGeometry.cell("hiragana-p1",595,842,230,150)==null)throw new AssertionError("Practice cells");System.out.println("54 kana lesson geometries, 151 contours, 21 choices and assistance grid mapping passed.");}
}
